# Shop web
Delivery planning offers stop reordering, reason prompts, uploaded proposals and customer scheduling.
The server accepts a 1-based destination rank among active stops. Stop history is retained after a stop is removed.
A change to a started, unfinished stop requires a reason. Uploads belong to their selected store.
Scheduling follows the server domain's delivery window. Run `bun test`; all dates and uploads are synthetic.
export type Stop={id:string;position:number;removed?:boolean;startedOn?:string;status:'NEW'|'IN_PROGRESS'|'POSTPONED'|'DONE'};
export const requiresReason=(stop:Stop)=>Boolean(stop.startedOn)&&stop.status!=='DONE';
export function deliveryWindow(notice:{sentAt:number},appointments:{at:number;status:string}[],now:number){const next=appointments.filter(a=>a.status!=='CANCELLED'&&a.status!=='HELD'&&a.at>now).sort((a,b)=>a.at-b.at)[0];return next?{from:notice.sentAt,to:next.at}:undefined;}
import type {Stop} from './domain';
export function moveUp(stops:Stop[],activeIndex:number){return {id:stops[activeIndex].id,position:stops[activeIndex-1].position};}
export const screenRequiresReason=(stop:Stop)=>stop.status==='IN_PROGRESS';
export function fitsWindow(at:number,notice:{sentAt:number},appointments:{at:number;status:string}[],now:number){const next=appointments.filter(a=>a.status!=='CANCELLED').sort((a,b)=>a.at-b.at)[0];return Boolean(next && at<next.at);}
