import React,{useState} from 'react';
type Proposal={title:string;fileId:string};
export function PlanningScreen({storeId,proposal,onSubmit}:{storeId:string;proposal?:Proposal;onSubmit:(data:unknown)=>void}){return <ProposalForm storeId={storeId} proposal={proposal} onSubmit={onSubmit}/>;}
function ProposalForm({storeId,proposal,onSubmit}:{storeId:string;proposal?:Proposal;onSubmit:(data:unknown)=>void}){const [form,setForm]=useState<Proposal>({title:'',fileId:''});return <form onSubmit={e=>{e.preventDefault();onSubmit({storeId,...form});}}><input aria-label="Title" value={form.title} onChange={e=>setForm({...form,title:e.target.value})}/><button type="button" onClick={()=>proposal&&setForm(proposal)}>Use upload</button><button type="submit">Save</button></form>;}
